def add_drums(pat, intensity=2, fill=False, crash=False, breakdown=False):
    if crash:
        setcell(pat,0,CH_OPEN,p('C',4),I_OPEN,36)
    if breakdown:
        # sparse first half, then build back up
        kicks=[0,32,44,48,60]
        snares=[24,40,56]
        hats=list(range(0,64,4)) + list(range(48,64,2))
    elif intensity==0:
        kicks=[0,32]
        snares=[24,56]
        hats=list(range(0,64,4))
    elif intensity==1:
        kicks=[0,16,30,32,48,62]
        snares=[8,24,40,56]
        hats=list(range(0,64,4)) + list(range(32,64,4))
    else:
        kicks=[0,12,16,30,32,44,48,62]
        snares=[8,24,40,56]
        hats=list(range(0,64,2))
    for r in kicks:
        vol=60 if r%16==0 else 50
        setcell(pat,r,CH_KICK,p('C',4),I_KICK,vol)
    for r in snares:
        setcell(pat,r,CH_SNARE,p('C',4),I_SNARE,50 if r in [8,24,40,56] else 38)
