def add_arps(pat, prog, intensity=2, variation=0):
    for si,cname in enumerate(prog):
        base=si*16; c=chords[cname]
        root=c['root']; param=c['param']
        # left: machine-gun triad arp. effect-only rows continue the 0xy shimmer.
