        # right: answering pinpricks, using 7th/sus tones now and then
        if intensity>=1:
            rtrig=[1,5,9,13] if intensity<2 else [1,3,5,9,11,13]
            for k,rr in enumerate(rtrig):
                if cname=='B7' and k%2==0:
