import numpy as np, base64, json, os, math, random

FS = 8363  # FT2 default C-4 sample playback rate
rng = np.random.default_rng(0xC0DEFACE)

# ---------- synthesis helpers ----------
def norm(x, peak=0.92):
    x = np.asarray(x, dtype=np.float32)
    m = float(np.max(np.abs(x))) if len(x) else 0.0
    if m > 1e-9:
        x = x / m * peak
    return x.astype(np.float32)

def fade_edges(x, a=16, r=64):
    x = x.astype(np.float32).copy()
    if a and len(x)>a:
        x[:a] *= np.linspace(0,1,a,endpoint=False,dtype=np.float32)
    if r and len(x)>r:
        x[-r:] *= np.linspace(1,0,r,endpoint=False,dtype=np.float32)
    return x

def onepole_lp(x, a=0.15):
    y = np.empty_like(x, dtype=np.float32)
    last = 0.0
    for i,v in enumerate(x):
        last += a * (float(v) - last)
        y[i] = last
    return y

def onepole_hp(x, a=0.98):
    # y[n] = a*(y[n-1] + x[n] - x[n-1])
    y = np.empty_like(x, dtype=np.float32)
    last_y = 0.0; last_x = 0.0
    for i,v in enumerate(x):
        yy = a*(last_y + float(v) - last_x)
        y[i] = yy
        last_y = yy; last_x = float(v)
    return y

def saw(f, t):
    ph = (f*t) % 1.0
    return (2*ph - 1.0).astype(np.float32)

def pulse(f, t, duty=0.5):
    ph = (f*t) % 1.0
    return np.where(ph < duty, 1.0, -1.0).astype(np.float32)

def tri(f, t):
    ph = (f*t) % 1.0
    return (4*np.abs(ph-0.5)-1.0).astype(np.float32)

def sine_from_freq_env(freq, t):
    # integrate variable frequency
    phase = 2*np.pi*np.cumsum(freq)/FS
    return np.sin(phase).astype(np.float32)

C4 = 261.625565

def sample_kick():
    n=int(0.50*FS); t=np.arange(n)/FS
    f = 42 + 150*np.exp(-t*22) + 35*np.exp(-t*80)
    s = sine_from_freq_env(f,t)
    env = np.exp(-t*8.2)
    click = rng.normal(0,1,n).astype(np.float32) * np.exp(-t*115)
    click = onepole_hp(click, 0.90)
    body = 0.95*s*env + 0.20*click
    body += 0.13*np.sin(2*np.pi*92*t)*np.exp(-t*18)
    return fade_edges(norm(np.tanh(body*1.4),0.96),4,96)

def sample_snare():
    n=int(0.42*FS); t=np.arange(n)/FS
    noise = rng.normal(0,1,n).astype(np.float32)
    noise = onepole_hp(noise,0.82)
    bursts = np.zeros(n,dtype=np.float32)
    for d,a in [(0.000,1.0),(0.011,0.75),(0.026,0.55),(0.043,0.35)]:
        bursts += a*np.exp(-np.maximum(0,t-d)*32)*(t>=d)
    tone = np.sin(2*np.pi*(185+30*np.exp(-t*20))*t).astype(np.float32)*np.exp(-t*12)
    snap = onepole_hp(rng.normal(0,1,n).astype(np.float32),0.95)*np.exp(-t*45)
    x = 0.72*noise*bursts + 0.38*tone + 0.18*snap
    return fade_edges(norm(np.tanh(x*1.3),0.94),4,96)

def sample_hat(closed=True):
    dur = 0.09 if closed else 0.62
    n=int(dur*FS); t=np.arange(n)/FS
    noise = rng.normal(0,1,n).astype(np.float32)
    noise = onepole_hp(noise,0.96)
    # metallic square cluster, deliberately aliased/chippy
    metal = (pulse(2300,t,0.49)+pulse(2910,t,0.47)+pulse(3530,t,0.43)+pulse(1770,t,0.51))*0.25
    env = np.exp(-t*(70 if closed else 7.5))
    if not closed:
        env *= (1-np.exp(-t*70))
    x = (0.72*noise + 0.35*metal) * env
    return fade_edges(norm(x,0.85 if closed else 0.82),2,64)

def sample_bass():
    n=int(0.52*FS); t=np.arange(n)/FS
    f=C4
    # slightly hollow PWM/saw bass, with quick transient
    ph=(f*t)%1.0
    pw = np.where(ph < (0.34 + 0.04*np.sin(2*np.pi*5*t)), 1.0, -1.0)
    w = 0.48*pw + 0.32*saw(f,t) + 0.22*np.sin(2*np.pi*f*t) + 0.12*np.sin(2*np.pi*2*f*t)
    w = np.tanh(w*1.6)
    env=(1-np.exp(-t*180))*np.exp(-t*4.4)
    click = (rng.normal(0,1,n).astype(np.float32)*np.exp(-t*80))*0.045
    x = w*env + click
    return fade_edges(norm(x,0.90),8,128)

def sample_acid_bass():
    n=int(0.34*FS); t=np.arange(n)/FS
    f=C4
    w = 0.70*saw(f,t) + 0.28*saw(2*f,t) + 0.22*pulse(f,t,0.40)
    # moving one-pole lowpass for pseudo-resonant pluck
    env=(1-np.exp(-t*190))*np.exp(-t*7.5)
    # bright attack emphasized, then darker tail
    x = np.tanh(w*(1.2+1.2*np.exp(-t*35))) * env
    return fade_edges(norm(x,0.88),8,96)

def sample_arp():
    n=int(0.24*FS); t=np.arange(n)/FS
    f=C4
    w = 0.46*pulse(f,t,0.25) + 0.37*saw(f,t) + 0.22*tri(2*f,t) + 0.08*rng.normal(0,1,n)
    env=(1-np.exp(-t*260))*np.exp(-t*16.0)
    x = np.tanh(w*1.4)*env
    return fade_edges(norm(x,0.78),4,80)

def sample_lead():
    n=int(0.86*FS); t=np.arange(n)/FS
    f=C4
    vib = 0.004*np.sin(2*np.pi*5.2*t)*(1-np.exp(-t*8))
    tt = t + vib/f
    w = 0.50*pulse(f,tt,0.38) + 0.36*saw(f*1.005,t) + 0.22*saw(f*0.997,t) + 0.16*np.sin(2*np.pi*2*f*t)
    env=(1-np.exp(-t*100))*np.exp(-t*3.05)
    # slightly emphasize the first 90 ms
    env *= (0.78 + 0.28*np.exp(-t*18))
    x = np.tanh(w*1.45)*env
    return fade_edges(norm(x,0.82),8,180)

def sample_bell():
    n=int(0.75*FS); t=np.arange(n)/FS
    f=C4
    mod = np.sin(2*np.pi*f*2.01*t)*2.2*np.exp(-t*4.5)
    x = np.sin(2*np.pi*f*t + mod) + 0.32*np.sin(2*np.pi*3.01*f*t)*np.exp(-t*5.5)
    env=(1-np.exp(-t*180))*np.exp(-t*4.8)
    return fade_edges(norm(x*env,0.78),6,160)

def sample_stab():
    n=int(0.58*FS); t=np.arange(n)/FS
    f=C4
    w = 0.42*saw(f,t) + 0.28*saw(f*1.010,t) + 0.22*pulse(f*0.996,t,0.50) + 0.16*tri(2*f,t)
    env=(1-np.exp(-t*130))*np.exp(-t*5.4)
    x = np.tanh(w*1.15)*env
    return fade_edges(norm(x,0.74),8,128)

def sample_riser():
    n=int(0.82*FS); t=np.arange(n)/FS
    noise = onepole_hp(rng.normal(0,1,n).astype(np.float32),0.97)
    f0=500; f1=3600
    f = f0*(f1/f0)**(t/max(t[-1],1e-6))
    tone = sine_from_freq_env(f,t)
    env = (t/t[-1])**1.8
    x = (0.55*noise + 0.45*tone) * env
    # a tiny silence at the very end prevents rough loops
    return fade_edges(norm(x,0.72),16,220)

def sample_tom():
    n=int(0.30*FS); t=np.arange(n)/FS
    f = 300*np.exp(-t*15) + 82
    s = sine_from_freq_env(f,t)
    w = np.tanh((s + 0.35*pulse(150,t,0.44))*1.4)
    env=(1-np.exp(-t*120))*np.exp(-t*7.0)
    return fade_edges(norm(w*env,0.88),4,96)

def sample_blip():
    n=int(0.16*FS); t=np.arange(n)/FS
    f=C4*2
    w=0.6*pulse(f,t,0.2)+0.4*np.sin(2*np.pi*f*1.5*t)
    env=(1-np.exp(-t*260))*np.exp(-t*22)
    return fade_edges(norm(w*env,0.72),4,64)

