# ---------- arrangement helpers ----------
def add_drums(pat, intensity=2, fill=False, crash=False, breakdown=False):
    if crash:
        setcell(pat,0,CH_OPEN,p('C',4),I_OPEN,36)
    if breakdown:
        # sparse first half, then build back up
        kicks=[0,32,44,48,60]
        snares=[24,40,56]
        hats=list(range(0,64,4)) + list(range(48,64,2))
    elif intensity==0:
        kicks=[0,32]
        snares=[24,56]
        hats=list(range(0,64,4))
    elif intensity==1:
        kicks=[0,16,30,32,48,62]
        snares=[8,24,40,56]
        hats=list(range(0,64,4)) + list(range(32,64,4))
    else:
        kicks=[0,12,16,30,32,44,48,62]
        snares=[8,24,40,56]
        hats=list(range(0,64,2))
    for r in kicks:
        vol=60 if r%16==0 else 50
        setcell(pat,r,CH_KICK,p('C',4),I_KICK,vol)
    for r in snares:
        setcell(pat,r,CH_SNARE,p('C',4),I_SNARE,50 if r in [8,24,40,56] else 38)
    # ghost snares for high intensity
    if intensity>=2 and not breakdown:
        for r in [22,38,54]:
            setcell(pat,r,CH_SNARE,p('C',4),I_SNARE,24)
    if breakdown:
        for r in [52,54,58,60,62]:
            setcell(pat,r,CH_SNARE,p('C',4),I_SNARE,28 + (r%4)*3)
    # hats
    for r in hats:
        if r>=64: continue
        if r % 8 == 0: vol=23
        elif r % 4 == 0: vol=20
        else: vol=14 if intensity>=2 else 0
        if vol>0:
            setcell(pat,r,CH_HAT,p('C',5),I_HAT,vol)
    # open offbeat hats
    if intensity>=1 and not breakdown:
        for r in [4,20,36,52]:
            setcell(pat,r,CH_OPEN,p('C',4),I_OPEN,25 if intensity==1 else 29)
    elif breakdown:
        for r in [36,52]:
            setcell(pat,r,CH_OPEN,p('C',4),I_OPEN,26)
    if fill:
        # last-beat crunchy snare/tom fill
        for r,v in [(56,42),(58,32),(60,44),(61,28),(62,48),(63,30)]:
            setcell(pat,r,CH_SNARE,p('C',4),I_SNARE,v)
        setcell(pat,60,CH_PERC,p('C',4),I_TOM,38)
        setcell(pat,62,CH_EXTRA,p('G',4),I_TOM,34)

def add_bass(pat, prog, variant=0, drop=False):
    for si,cname in enumerate(prog):
        base=si*16; c=chords[cname]
        br=c['bass']; fifth=c.get('fifth', br+7)
        if drop and si < 2:
            events=[(0,br,48),(8,fifth,38)]
        elif variant==1:
            events=[(0,br,52),(5,br+12,34),(8,fifth,44),(11,br+12,36),(14,br,32)]
        elif variant==2:
            events=[(0,br,52),(4,fifth,40),(6,br+12,34),(8,br,45),(12,fifth,38),(14,br+12,32)]
        else:
            events=[(0,br,52),(6,br+12,34),(8,fifth,44),(12,br,36)]
        for rr,npitch,vol in events:
            inst=I_ACID if (variant==2 and rr in (4,12)) else I_BASS
            setcell(pat,base+rr,CH_BASS,npitch,inst,vol)

def add_stabs(pat, prog, density=1):
    for si,cname in enumerate(prog):
        base=si*16; c=chords[cname]
        st=c['stab']
        rows=[0]
        if density>=1: rows.append(8)
        if density>=2: rows += [12]
        for rr in rows:
            v0=25 if rr==0 else (19 if rr==8 else 15)
            setcell(pat,base+rr,CH_STAB1,st[0],I_STABL,v0)
            setcell(pat,base+rr,CH_STAB2,st[1],I_STABC,max(12,v0-3))
            setcell(pat,base+rr,CH_STAB3,st[2],I_STABR,v0)

def add_arps(pat, prog, intensity=2, variation=0):
    for si,cname in enumerate(prog):
        base=si*16; c=chords[cname]
        root=c['root']; param=c['param']
        # left: machine-gun triad arp. effect-only rows continue the 0xy shimmer.
        if intensity==0:
            trig=[0,4,8,12]
        elif intensity==1:
            trig=[0,2,4,8,10,12]
        else:
            trig=list(range(0,16,2))
        for k,rr in enumerate(trig):
            if variation==2:
                offs=[12,19,12,24,19,12,15,19][k%8]
            elif variation==1:
                offs=[12,24,19,12,15,19,24,19][k%8]
            else:
                offs=[12,19,24,19,12,15,19,24][k%8]
            vol = 27 + (4 if rr%8==0 else 0) - (0 if intensity>=2 else 3)
            setcell(pat,base+rr,CH_ARPL,root+offs,I_ARPL,vol,0,param)
            # keep arpeggio effect alive on following row
            if base+rr+1 < base+16:
                setcell(pat,base+rr+1,CH_ARPL,effect=0,param=param)
        # right: answering pinpricks, using 7th/sus tones now and then
        if intensity>=1:
            rtrig=[1,5,9,13] if intensity<2 else [1,3,5,9,11,13]
            for k,rr in enumerate(rtrig):
                if cname=='B7' and k%2==0:
                    note=chords[cname].get('sev',root+10)+12
                    ep=0x03
                else:
                    offseq=[24,19,27,24,31,19]
                    note=root+offseq[k%len(offseq)]
                    ep=param
                setcell(pat,base+rr,CH_ARPR,note,I_ARPR,19+(4 if rr%8==1 else 0),0,ep)
                if intensity>=2 and base+rr+1<base+16:
                    setcell(pat,base+rr+1,CH_ARPR,effect=0,param=ep)

def add_blips(pat, rows):
    for r,note,vol in rows:
        setcell(pat,r,CH_PERC,note,I_BLIP,vol)

def add_fx(pat, at=48, vol=25):
    setcell(pat,at,CH_FX,p('C',4),I_FX,vol)

def add_melody(pat, events, echo=True, inst=I_LEAD, ch=CH_LEAD, vol_default=46, echo_delay=3):
    for ev in events:
        if len(ev)==2:
            r,npitch=ev; vol=vol_default
        elif len(ev)==3:
            r,npitch,vol=ev
        else:
            r,npitch,vol,_=ev
        setcell(pat,r,ch,npitch,inst,vol)
        if echo and r+echo_delay < 64:
            setcell(pat,r+echo_delay,CH_ECHO,npitch,I_ECHO,max(14,int(vol*0.55)))

def add_counter(pat, events, inst=I_BELL, vol_default=28):
    for ev in events:
        if len(ev)==2:
            r,npitch=ev; vol=vol_default
        else:
            r,npitch,vol=ev
        setcell(pat,r,CH_COUNTER,npitch,inst,vol)

