        add_bass(pat, prog, variant=1, drop=True)
        add_stabs(pat, prog, density=2)
        add_arps(pat, prog, intensity=1, variation=1)
        add_fx(pat,48,20)
    else:
        inten=2 if pat not in (1,6) else 1
        add_drums(pat, intensity=inten, fill=(pat in [3,7,11,15]), crash=(pat in [2,6,8,10,13]))
        add_bass(pat, prog, variant=(pat%3))
        add_stabs(pat, prog, density=1 if pat in [1,2,6,8,13,15] else 2)
        add_arps(pat, prog, intensity=inten, variation=pat%3)
        if pat in [3,7,11,15]: add_fx(pat,48,23 if pat!=15 else 25)
    # melody and echo
    if melodies[pat]:
        delay=4 if pat in [5,12] else 3
        add_melody(pat, melodies[pat], echo=True, echo_delay=delay)
    # counter-melody/bell on selected sections
    if pat in [2,3,8,9,13,14]:
        # thirds/harmony stabs in gaps
        ce=[]
        for r,npitch,*rest in melodies[pat][::4]:
            if r+1<64:
                ce.append((r+1,npitch-12,24))
        add_counter(pat, ce, I_BELL, 24)
    if pat in [6,7,10,11,15]:
        ce=[(4,E5,24),(12,G5,22),(20,A5,23),(28,B5,24),(36,D6,25),(44,C6,23),(52,B5,24),(60,A5,22)]
        if pat in [10,11]:
            ce=[(r+1,n+7,22) for r,n,_ in ce if r+1<64]
        add_counter(pat, ce, I_BELL, 24)
    # little digital sparkle near ends
    if pat not in [5,12]:
        add_blips(pat, [(14,B5,16),(46,D6,17),(61,FS6 if pat%2 else E6,18)])

# Save module
os.makedirs('/workspace/submission', exist_ok=True)
call('module_save', {'path':'/workspace/submission/tune.xm','format':'xm'})

with open('/workspace/tune_batch.json','w') as f:
    json.dump(calls,f)
print(f'wrote {len(calls)} ft2 calls to /workspace/tune_batch.json')
print('sample lengths:', {k:len(v) for k,v in samples.items()})
